namespace Witcher3ModManager.Models;

/// <summary>
/// A documented ignore rule for false-positive conflict files.
/// Rules must satisfy three conditions:
/// 1. Present in nearly every mod (e.g. auto-generated by WolvenKit)
/// 2. Overwriting them does NOT change game behavior
/// 3. They provide zero value in diagnosing real conflicts
/// </summary>
public record IgnoredConflictRule(string Pattern, string Reason);
